// 감시 종목은 «김프 종목 유니버스 스캐너»(2PpPAsVnBNatWQiN)가 6시간마다 갱신하는
// kimchi_coin_universe 테이블에서 읽어온다. 고정 목록이 아니다.
//
// 테이블에 있는 종목은 tradable 여부와 무관하게 전부 가격을 기록한다. 이유가 둘 있다:
//   ① 보유 중인 포지션이 편출되면 현재가가 끊겨 청산 판정 자체가 멈춘다(영영 못 나간다).
//   ② 이력이 끊기면 재편입될 때 3일 이동평균을 처음부터 다시 쌓아야 한다.
// 실제 진입 대상 선별은 «진입 가능 여부 판단»에서 tradable로 따로 거른다.
const FALLBACK = ['BTC','ETH','SOL','BNB','XRP','ADA','AVAX','DOT','LINK','POL','DOGE','TRX','XLM','SHIB','BCH','UNI','AAVE','SUSHI','LDO','ICP','NEAR','HBAR','XTZ','DYDX','ARB','GMX','IMX','INJ','GRT','SUI','HYPE'];

let names = $('거래 종목 조회').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && r.coin; })
  .map(function (r) { return String(r.coin).toUpperCase(); });

// 테이블을 못 읽으면 봇이 통째로 멈추므로 예전 고정 목록으로 되돌린다
const usedFallback = names.length === 0;
if (usedFallback) names = FALLBACK;

const seen = {};
const coins = [];
names.forEach(function (n) {
  if (seen[n]) return;
  seen[n] = true;
  coins.push({ name: n, korbitSymbol: n.toLowerCase() + '_krw', okxInstId: n + '-USDT-SWAP' });
});

// 코빗 응답 형태: { success: true, data: [ { symbol: 'BTC_KRW', close: 130000000, ... }, ... ] }
// 종목을 동적으로 고르므로 심볼 필터 없이 전 종목을 받아와 여기서 짝을 맞춘다.
const korbitBody = $('코빗 가격 조회').first().json;
const korbitRows = (korbitBody && korbitBody.data) ? korbitBody.data : [];

// OKX 응답 형태: { code: '0', msg: '', data: [ { instId: 'BTC-USDT-SWAP', last: '79720.1', ... }, ... ] }
const okxBody = $('OKX 가격 조회').first().json;
const okxRows = (okxBody && okxBody.data) ? okxBody.data : [];

// 코빗은 원화(KRW) 마켓만 있어서, 환율로 달러(USD) 환산한 뒤에 OKX(USDT) 가격과 비교해야 함
const fxBody = $('환율 조회').first().json;
const usdKrwRate = (fxBody && fxBody.rates && fxBody.rates.KRW) ? Number(fxBody.rates.KRW) : null;

const now = new Date().toISOString();
const results = [];

if (usdKrwRate) {
  for (let i = 0; i < coins.length; i++) {
    const coin = coins[i];

    const korbitRow = korbitRows.find(function (r) {
      return String(r.symbol).toUpperCase() === coin.korbitSymbol.toUpperCase();
    });
    const okxRow = okxRows.find(function (r) {
      return r.instId === coin.okxInstId;
    });

    // 코빗 또는 OKX 둘 중 하나라도 가격이 없으면(상장 폐지 등) 이번 코인은 건너뜀
    if (!korbitRow || !okxRow) continue;

    const korbitPriceKrw = Number(korbitRow.close);
    const korbitPriceUsd = korbitPriceKrw / usdKrwRate; // 원화 -> 달러 환산
    const foreignPrice = Number(okxRow.last);

    // 김프(%) = (국내가(달러 환산) / 해외가 - 1) x 100
    const premium = Math.round(((korbitPriceUsd / foreignPrice - 1) * 100) * 10000) / 10000;

    results.push({
      json: {
        coin: coin.name,
        korbitPrice: korbitPriceKrw,
        foreignPrice: foreignPrice,
        usdKrwRate: usdKrwRate,
        premium: premium,
        checkedAt: now
      }
    });
  }
}

return results;

// 설정값: 3일 이동평균 기준으로 진입/청산 신호를 판정
//
// 2026-09-20 갱신. 6년 백테스트(120조합 x 12종목, 학습 70% / 검증 30%)로 고른 값이다.
// 이전 설정(진입 1.0σ)은 검증 구간에서 연 -14.58%, 승률 42.8%, MDD $2,924로 졌다.
// 아무 자리에나 들어가 6년에 15,484건을 거래한 결과였다. 거래를 줄이고 자리를 고른다.
const ENTRY_SIGMA = 2.0; // 평균보다 2시그마 아래로 떨어지면 진입

// 청산은 평균 도달 즉시가 아니라 평균+0.25σ까지 기다린다.
// 신호를 본 뒤 실제 체결까지 시간이 걸리는데, 평균에 닿자마자 나가려 하면
// 그 사이에 이미 되돌아와 손실로 끝난다. 여유를 두는 쪽이 수익이 난다.
// +0.5σ보다 +0.25σ가 거래를 늘리면서 최대 낙폭을 줄인다(수익/MDD 9.22 vs 7.67).
// ⚠️ 이 값은 «손익 계산» 노드와 반드시 같아야 한다.
const EXIT_SIGMA_OFFSET = 0.25;

const MIN_DATA_POINTS = 10; // 데이터가 이보다 적으면 통계 신뢰 안 함(스킵)
const MAX_SIGMA_PERCENT = 2.5; // 표준편차가 이보다 크면 "너무 변동성이 큼"으로 보고 이번 회차에는 신호를 내지 않음(일시 제외, 가라앉으면 자동 복귀)

const rows = $input.all().map(function (item) { return item.json; });

// 코인별로 묶기 (한 번의 조회에 여러 코인의 이력이 섞여서 들어옴)
const byCoin = {};
rows.forEach(function (r) {
  if (!byCoin[r.coin]) byCoin[r.coin] = [];
  byCoin[r.coin].push(r);
});

const results = [];

Object.keys(byCoin).forEach(function (coin) {
  const list = byCoin[coin].slice().sort(function (a, b) {
    return new Date(b.checkedAt).getTime() - new Date(a.checkedAt).getTime();
  });

  const n = list.length;
  if (n < MIN_DATA_POINTS) return; // 아직 데이터가 부족하면 이번 코인은 판정하지 않음

  const current = list[0]; // 가장 최근 값(방금 저장한 이번 회차 값)

  const sum = list.reduce(function (s, r) { return s + r.premium; }, 0);
  const ma = sum / n;
  const variance = list.reduce(function (s, r) { return s + Math.pow(r.premium - ma, 2); }, 0) / n;
  const sigma = Math.sqrt(variance);
  const lower = ma - ENTRY_SIGMA * sigma;
  const upper = ma + EXIT_SIGMA_OFFSET * sigma;
  const tooVolatile = sigma > MAX_SIGMA_PERCENT;

  let signal = null;
  if (!tooVolatile) {
    if (current.premium < lower) {
      signal = 'ENTRY'; // 평균보다 통계적으로 많이 낮음 -> 저평가 구간
    } else if (current.premium > upper) {
      signal = 'EXIT'; // 평균을 넘어 여유까지 회복함 -> 청산 시점
    }
  }
  // tooVolatile이면 signal은 계속 null -> 이번 회차에는 진입/청산 없음. 다음 회차에 sigma가 낮아지면 자동으로 다시 판정 대상이 됨

  results.push({
    json: {
      coin: coin,
      premium: current.premium,
      korbitPrice: current.korbitPrice,
      foreignPrice: current.foreignPrice,
      ma: ma,
      sigma: sigma,
      lower: lower,
      upper: upper,
      dataPoints: n,
      tooVolatile: tooVolatile,
      signal: signal
    }
  });
});

return results;

const MAX_POSITIONS = 4; // 동시에 열 수 있는 최대 가상 포지션 수
// 6년 백테스트상 5자리까지는 청산 위험이 늘지 않는다(증거금 사용률 3자리 39.7% -> 5자리 32.4%).
// 그럼에도 4로 두는 건 시드의 20%를 현금으로 남겨
// 백테스트로 측정되지 않는 위험(거래소 장애, 증거금 요구 변경)에 대응하기 위함.
// 운영이 안정되면 5로 올린다.

const CHECK_LIMIT = 8;   // 호가 검증까지 돌려볼 후보 수.

// 거래 대상은 스캐너가 관리한다 — 호가 스프레드 중앙값이 3일(12회) 연속 0.8% 이하일 때만
// tradable이 켜진다. 스프레드가 넓다는 건 사고팔 상대가 없다는 뜻이고,
// 그런 종목의 김프는 먹을 수 있는 기회가 아니라 거래가 없어서 생긴 허상이다.
const tradable = {};
$('거래 종목 조회').all().forEach(function (i) {
  const r = i.json;
  if (r && r.coin && r.tradable === true) tradable[String(r.coin).toUpperCase()] = true;
});
// 테이블을 못 읽었을 때 전체 진입을 막아버리지 않도록, 비어 있으면 관문을 해제한다
const hasUniverse = Object.keys(tradable).length > 0;

const openPositions = [];
const seenIds = {};
$input.all().forEach(function (item) {
  const row = item.json;
  if (!row || !row.coin) return;
  if (seenIds[row.id]) return;
  seenIds[row.id] = true;
  openPositions.push(row);
});

const slots = MAX_POSITIONS - openPositions.length;
if (slots <= 0) return [];

const openCoins = openPositions.map(function (p) { return p.coin; });

const candidates = $('MA·신호 판정').all()
  .map(function (item) { return item.json; })
  .filter(function (s) { return s.signal === 'ENTRY'; })
  .filter(function (s) { return openCoins.indexOf(s.coin) === -1; })
  .filter(function (s) { return !hasUniverse || tradable[s.coin] === true; });

candidates.forEach(function (s) {
  s.zScore = s.sigma > 0 ? (s.ma - s.premium) / s.sigma : 0;
});
candidates.sort(function (a, b) { return b.zScore - a.zScore; });

return candidates.slice(0, CHECK_LIMIT).map(function (s) {
  return {
    json: {
      coin: s.coin,
      premium: s.premium,
      ma: s.ma,
      sigma: s.sigma,
      lower: s.lower,
      korbitPrice: s.korbitPrice,
      foreignPrice: s.foreignPrice, // 호가 기준 김프 재계산 + 가격손절 기준점
      zScore: Math.round(s.zScore * 100) / 100,
      slots: slots,
      candidateCount: candidates.length,
      openCount: openPositions.length
    }
  };
});

// 편도 수수료: 국내 0%(코빗 2026-08-24~2027-08-24 원화마켓 무료) + 해외 지정가 0.02%
const FEE_RATE = 0.0002;
const EXIT_SIGMA_OFFSET = 0.25; // MA·신호 판정과 같은 값이어야 한다 (2026-09-20: 0.5 -> 0.25)

const openTrade = $('청산할 포지션 조회').item.json;
const exitSignal = $('MA·신호 판정').item.json;

const ob = ($json && $json.data) ? $json.data : {};
const bids = ob.bids || [];
const fxBody = $('환율 조회').first().json;
const fx = (fxBody && fxBody.rates && fxBody.rates.KRW) ? Number(fxBody.rates.KRW) : null;
const foreignPrice = Number(exitSignal.foreignPrice);

// 청산 신호는 마지막 체결가로 판정하지만, 실제로 팔리는 건 최우선 매수호가다.
// 가격이 내려가는 구간에서는 체결가가 호가보다 높게 남아 있어서,
// "회복했다"고 본 가격에 정작 팔 수가 없는 일이 생긴다.
// 진입과 대칭으로, 실제 매도가로 다시 계산해 그래도 청산 조건을 만족할 때만 나간다.
let exitPremium = Number(exitSignal.premium);
let exitPrice = Number(exitSignal.korbitPrice);
let verified = false;
let skipReason = '';

if (fx && foreignPrice && bids.length) {
  const bid = Number(bids[0].price);
  if (bid) {
    exitPrice = bid;
    exitPremium = Math.round(((bid / fx / foreignPrice) - 1) * 100 * 10000) / 10000;
    const threshold = Number(exitSignal.ma) + EXIT_SIGMA_OFFSET * Number(exitSignal.sigma);
    if (exitPremium > threshold) {
      verified = true;
    } else {
      skipReason = '실매도 기준 ' + exitPremium.toFixed(2) + '% ≤ 청산선 ' + threshold.toFixed(2) + '%';
    }
  } else {
    skipReason = '호가 파싱 실패';
  }
} else {
  skipReason = '호가/환율 없음';
}

// 검증을 통과하지 못하면 포지션을 그대로 둔다.
// 다음 회차에 다시 신호가 뜨면 그때 재판정한다.
if (!verified) {
  return { json: { shouldExit: false, coin: openTrade.coin, skipReason: skipReason } };
}

const positionSize = Number(openTrade.positionSize);
const entryPremium = Number(openTrade.entryPremium);

// 국내 현물 롱 + 해외 선물 숏을 합치면 코인 시세는 상쇄되고
// 두 시장의 가격차(김프)가 변한 만큼만 손익이 된다.
const premiumGain = exitPremium - entryPremium;
const grossProfit = Math.round((positionSize * premiumGain / 100) * 100) / 100;
const feeExit = Math.round(positionSize * FEE_RATE * 10000) / 10000;
const netProfit = Math.round((grossProfit - Number(openTrade.feeEntry) - feeExit) * 100) / 100;
const heldMinutes = Math.round((Date.now() - new Date(openTrade.entryTime).getTime()) / 60000);

return {
  json: {
    shouldExit: true,
    rowId: openTrade.id,
    coin: openTrade.coin,
    entryPremium: entryPremium,
    entryTime: openTrade.entryTime,
    heldMinutes: heldMinutes,
    exitPremium: exitPremium,
    exitPrice: exitPrice,
    grossProfit: grossProfit,
    feeExit: feeExit,
    netProfit: netProfit
  }
};

const ONE_DAY_MS = 24 * 60 * 60 * 1000;
const EXPECTED_RUNS_PER_DAY = 288; // 5분마다 실행 = 하루 288회
const nowMs = Date.now();
const cutoff = nowMs - ONE_DAY_MS;

const rows = $input.all().map(function (item) { return item.json; });
const recentRows = rows.filter(function (r) { return new Date(r.checkedAt).getTime() >= cutoff; });

// 코인별로 묶기
const byCoin = {};
recentRows.forEach(function (r) {
  if (!byCoin[r.coin]) byCoin[r.coin] = [];
  byCoin[r.coin].push(r);
});

const coinStats = [];
Object.keys(byCoin).sort().forEach(function (coin) {
  const list = byCoin[coin].slice().sort(function (a, b) {
    return new Date(a.checkedAt).getTime() - new Date(b.checkedAt).getTime();
  });
  const premiums = list.map(function (r) { return r.premium; });
  const sum = premiums.reduce(function (s, v) { return s + v; }, 0);
  const avg = sum / premiums.length;
  const min = Math.min.apply(null, premiums);
  const max = Math.max.apply(null, premiums);
  const latest = list[list.length - 1];

  coinStats.push({
    coin: coin,
    current: latest.premium,
    avg: avg,
    min: min,
    max: max,
    dataPoints: list.length
  });
});

// 정상 동작 여부 판단: 실행 횟수가 충분한지 + 최신 데이터가 신선한지
const distinctTimestamps = {};
recentRows.forEach(function (r) { distinctTimestamps[r.checkedAt] = true; });
const actualRuns = Object.keys(distinctTimestamps).length;

let latestOverallMs = null;
recentRows.forEach(function (r) {
  const t = new Date(r.checkedAt).getTime();
  if (latestOverallMs === null || t > latestOverallMs) latestOverallMs = t;
});
const minutesSinceLastData = latestOverallMs !== null ? Math.round((nowMs - latestOverallMs) / 60000) : null;

const isHealthy = (actualRuns >= EXPECTED_RUNS_PER_DAY * 0.85) && (minutesSinceLastData !== null && minutesSinceLastData <= 15);

return [{
  json: {
    coinStats: coinStats,
    actualRuns: actualRuns,
    expectedRuns: EXPECTED_RUNS_PER_DAY,
    minutesSinceLastData: minutesSinceLastData,
    isHealthy: isHealthy,
    reportTime: new Date().toISOString()
  }
}];

const data = $json;
const kstStr = new Date(data.reportTime).toLocaleString('ko-KR', { timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });

const statusLine = data.isHealthy
  ? '✅ 정상 동작 중'
  : '⚠️ 점검이 필요할 수 있어요 (실행 누락 또는 최신 데이터 지연 의심)';

const lines = [];
lines.push('📋 김치 프리미엄 봇 상태 보고 (' + kstStr + ' KST)');
lines.push(statusLine);
lines.push('지난 24시간 실행: ' + data.actualRuns + '/' + data.expectedRuns + '회, 최신 데이터 ' + (data.minutesSinceLastData !== null ? data.minutesSinceLastData + '분 전' : '없음'));
lines.push('');
lines.push('💰 페이퍼 트레이딩 성과 (가상 시드 $' + data.paperSeedUsd.toLocaleString('en-US') + ')');
if (data.totalTrades > 0) {
  const profitSign = data.totalNetProfit >= 0 ? '+' : '';
  lines.push('누적 청산 거래: ' + data.totalTrades + '회 (승 ' + data.winTrades + ' / 승률 ' + data.winRate.toFixed(1) + '%)');
  lines.push('누적 손익: ' + profitSign + '$' + data.totalNetProfit.toFixed(2) + ' (원금 대비 ' + profitSign + data.returnPct.toFixed(2) + '%)');
} else {
  lines.push('아직 청산된 거래 없음');
}
const openCoinNames = data.openPositions.map(function (p) { return p.coin; }).join(', ');
lines.push('현재 보유 중인 가상 포지션: ' + data.openPositionsCount + '개' + (data.openPositionsCount > 0 ? (' (' + openCoinNames + ')') : ''));
lines.push('');
lines.push('코인별 24시간 김프 추이 (현재 | 평균 | 범위 | 표본수)');

data.coinStats.forEach(function (c) {
  lines.push('· ' + c.coin + ': ' + c.current.toFixed(2) + '% | 평균 ' + c.avg.toFixed(2) + '% | [' + c.min.toFixed(2) + '% ~ ' + c.max.toFixed(2) + '%] | ' + c.dataPoints + '개');
});

lines.push('');
lines.push('🔗 대시보드: https://kimchi-premium-dashboard-mu.vercel.app');

return [{ json: { content: lines.join('\n') } }];

const PAPER_SEED_USD = 10000; // 가상 시드: $10,000

const priceStats = $('24시간 통계 계산').first().json;

const trades = $input.all().map(function (item) { return item.json; });
const closedTrades = trades.filter(function (t) { return t.status === 'CLOSED'; });
const openTrades = trades.filter(function (t) { return t.status === 'OPEN'; });

const totalTrades = closedTrades.length;
const winTrades = closedTrades.filter(function (t) { return Number(t.netProfit) > 0; });
const winRate = totalTrades > 0 ? (winTrades.length / totalTrades * 100) : null;
const totalNetProfit = closedTrades.reduce(function (s, t) { return s + Number(t.netProfit || 0); }, 0);
const returnPct = totalNetProfit / PAPER_SEED_USD * 100;

const openList = openTrades.map(function (t) {
  return { coin: t.coin, entryPremium: Number(t.entryPremium) };
});

return [{
  json: Object.assign({}, priceStats, {
    paperSeedUsd: PAPER_SEED_USD,
    totalTrades: totalTrades,
    winTrades: winTrades.length,
    winRate: winRate,
    totalNetProfit: totalNetProfit,
    returnPct: returnPct,
    openPositionsCount: openTrades.length,
    openPositions: openList
  })
}];

// 마지막 체결가(close)는 거래가 뜸한 코인에서 몇 시간 전 가격일 수 있다.
// 그런 값으로 계산한 김프는 실제로는 살 수 없는 허수라서, 진입 직전에
// 실제 매수호가(ask)로 김프를 다시 계산해 검증한다.
const MAX_SPREAD_PERCENT = 1.0; // 호가 스프레드가 이보다 벌어지면 사실상 거래가 없는 종목으로 보고 제외

// --- 백테스트에서 검증된 진입 관문 ---
// 평균까지 회복했을 때 기대되는 이익이 본전 문턱의 이 배수는 되어야 진입한다.
// 본전 문턱 = 왕복 수수료 + 종목별 호가 스프레드.
// 수수료를 간신히 넘기는 자리에 들어가 본전도 못 챙기는 거래를 막는 장치다.
//
// 2026-09-20 갱신: 5 -> 3. 6년 탐색에서 진입 2.0σ 기준 3배가 가장 좋았다.
// 이 관문은 평소엔 거의 발동하지 않는다(6년에 16건 차이). σ가 작아지는 조용한
// 국면과 스프레드가 넓은 종목에서만 작동하는 보험이다.
const EDGE_MULTIPLE = 3;
const FEE_ROUND_TRIP_PCT = 0.04; // 국내 0%(코빗 무료) + 해외 지정가 0.02% x 2

const cand = $('진입 가능 여부 판단').item.json;

function reject(reason) {
  return { json: Object.assign({}, cand, { canEnter: false, rejectReason: reason }) };
}

const body = $json || {};
const ob = body.data || {};
const asks = ob.asks || [];
const bids = ob.bids || [];

const fxBody = $('환율 조회').first().json;
const fx = (fxBody && fxBody.rates && fxBody.rates.KRW) ? Number(fxBody.rates.KRW) : null;

if (!fx) return reject('환율 없음');
if (!asks.length || !bids.length) return reject('호가 없음');

const ask = Number(asks[0].price); // 실제로 사게 되는 가격
const bid = Number(bids[0].price); // 실제로 팔게 되는 가격
if (!ask || !bid) return reject('호가 파싱 실패');

const spread = (ask / bid - 1) * 100;
if (spread > MAX_SPREAD_PERCENT) {
  return reject('스프레드 ' + spread.toFixed(2) + '% > ' + MAX_SPREAD_PERCENT + '%');
}

// 기대수익 관문 (백테스트와 동일하게 체결가 기준 김프로 판정)
const breakEven = FEE_ROUND_TRIP_PCT + spread;
const expectedGain = Number(cand.ma) - Number(cand.premium);
if (expectedGain < breakEven * EDGE_MULTIPLE) {
  return reject('기대수익 ' + expectedGain.toFixed(2) + '%p < 문턱 ' + (breakEven * EDGE_MULTIPLE).toFixed(2) + '%p');
}

const foreignPrice = Number(cand.foreignPrice);
if (!foreignPrice) return reject('해외가 없음');

// 체결가가 아니라 실제 매수호가로 김프 재계산
const execPremium = Math.round(((ask / fx / foreignPrice) - 1) * 100 * 10000) / 10000;

// 재계산한 김프가 여전히 진입선 아래여야 진짜 기회다
if (!(execPremium < Number(cand.lower))) {
  return reject('실매수 기준 ' + execPremium.toFixed(2) + '% (진입선 ' + Number(cand.lower).toFixed(2) + '%)');
}

return {
  json: Object.assign({}, cand, {
    canEnter: true,
    tickerPremium: cand.premium, // 참고용: 체결가 기준 값
    premium: execPremium,        // 이후 기록·알림은 실매수 기준 값을 쓴다
    korbitPrice: ask,
    askPrice: ask,
    bidPrice: bid,
    spread: Math.round(spread * 100) / 100,
    breakEven: Math.round(breakEven * 100) / 100,
    expectedGain: Math.round(expectedGain * 100) / 100
  })
};

// 호가 검증을 통과한 후보 중에서만 남은 슬롯만큼 골라낸다.
// (상위 후보가 전부 유동성 미달이어도 그 아래 멀줦한 후보가 기회를 가진다)
//
// --- 2026-09-20: 순위 기준을 z-score → 순기대이익으로 바꿈 ---
// 자리가 4개뿐이라 후보가 자리보다 많으면 «누구를 먼저 넣느냐»가 성적을 바꿄다.
// z-score = (평균-김프)/σ 는 비용을 모른다. 거래가 뜸한 종목은 마지막 체결가가
// 낡아 김프가 싸 보이는데 σ는 그만큼 커지지 않아서 z-score만 크게 나온다.
// 관문(EDGE_MULTIPLE)은 통과/탈락만 보는 바닥이라 이걸 못 막는다 — 통과하기만
// 하면 순위 싸움에서 멀줦한 종목을 밀어낸다.
//
// 자리마다 같은 금액($1,000)이 들어가므로, 비율이 아니라 «자리 하나가 벌어올
// 기대 순이익(%p)»이 목적함수다. 6년 백테스트 검증 구간에서
// 연 +9.39% → +11.04%, 건당 $1.87 → $2.18, 수익/MDD 9.44 → 11.10.
// 비율(기대이익/본전문턱)로 세우면 효과가 거의 없었다(+9.53%).
//
// breakEven은 «체결가능 김프 검증»이 방금 실제 호가로 재서 넣어준 값이라,
// 백테스트가 쓰는 고정 스프레드표보다 정확하다.
const all = $input.all().map(function (item) { return item.json; });
if (!all.length) return [];

const slots = Number(all[0].slots) || 0;
const passed = all.filter(function (c) { return c.canEnter === true; });

// 순기대이익 = 평균까지 회복하면 벌 폭 − 이 종목 거래비용 (둘 다 %p)
// 값이 없는 경우에만 예전 기준(z-score)으로 되돌린다.
passed.forEach(function (c) {
  const gain = Number(c.expectedGain);
  const be = Number(c.breakEven);
  c.netEdge = (isFinite(gain) && isFinite(be)) ? (gain - be) : null;
});

passed.sort(function (a, b) {
  if (a.netEdge !== null && b.netEdge !== null) return b.netEdge - a.netEdge;
  if (a.netEdge !== null) return -1;   // 계산된 쪽을 앞에
  if (b.netEdge !== null) return 1;
  return b.zScore - a.zScore;          // 둘 다 없으면 예전 기준
});

return passed.slice(0, slots).map(function (c) { return { json: c }; });

